<template><section class="admin-panel"><h2>셀피 심사 대기 <span class="queue-count">{{data.total}}</span></h2><p class="subtle">기존 회원의 재인증과 신규 가입 셀피를 접수순으로 확인합니다.</p><p v-if="error" role="alert">{{error}}</p><table v-if="data.items.length"><thead><tr><th>회원</th><th>구분</th><th>제출 시각</th><th/></tr></thead><tbody><tr v-for="u in data.items" :key="u.userId"><td>{{u.nickname}} <small>#{{u.userId}}</small></td><td>{{u.status==='ACTIVE'?'기존 회원 재인증':'신규 가입'}}</td><td>{{new Date(u.submittedAt).toLocaleString('ko-KR')}}</td><td><button class="accent" @click="$emit('member',u.userId)">심사하기</button></td></tr></tbody></table><p v-else class="empty">{{busy?'불러오는 중…':'대기 중인 셀피가 없습니다.'}}</p><footer class="pagination"><button :disabled="busy||page===0" @click="page--;load()">이전</button>{{page+1}}<button :disabled="busy||(page+1)*30>=data.total" @click="page++;load()">다음</button></footer></section></template>
<script setup>import {ref,onMounted,onUnmounted} from 'vue';import api from '../api/api';defineEmits(['member']);const data=ref({total:0,items:[]}),page=ref(0),busy=ref(false),error=ref('');let disposed=false,timer;async function load(){if(busy.value)return;busy.value=true;try{const res=await api.get('/admin/selfies/pending',{params:{page:page.value}});if(!disposed){data.value=res.data;error.value='';if(page.value&&page.value*30>=res.data.total)page.value=0;}}catch(e){error.value=e.response?.data?.message||'심사 목록을 불러오지 못했습니다.';}finally{busy.value=false;}}onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load();},15000);window.addEventListener('admin-selfies-changed',load);});onUnmounted(()=>{disposed=true;clearInterval(timer);window.removeEventListener('admin-selfies-changed',load);});defineExpose({load});</script><style scoped>section{overflow-x:auto}h2{font-size:18px;margin:0 0 14px}.subtle{font-size:12px;color:#8b949d;margin-bottom:20px}table{width:100%;border-collapse:collapse;font-size:13px;white-space:nowrap}th{text-align:left;color:#82909f;font-weight:500;background:#fafbfc;padding:14px 16px;border-bottom:1px solid #e8edf2}td{padding:18px 16px;border-bottom:1px solid #eef0f3}td small{display:block;color:#9aa4af;font-size:11px;margin-top:4px}button{font:inherit;border:1px solid #dce1e7;border-radius:9px;padding:10px 16px;background:white;color:#536171;cursor:pointer}button.accent{background:#bd7452;color:white;border:0}button:disabled{opacity:.45;cursor:default}.pagination{display:flex;align-items:center;justify-content:center;gap:18px;padding:20px 0 0;font-size:12px}.empty{text-align:center;padding:40px;color:#98a1ab}.queue-count{display:inline-block;background:#d85445;color:white;border-radius:20px;padding:2px 9px;font-size:13px;margin-left:6px}</style>
